191: /**
192:  * Checks for filesystem changes using `git status`. If any changes are found, it means the
193:  * translation files have changed, and this may trigger a CI fail when running inside the CI.
194:  * @returns {boolean} True if changes were found, or if an error happened
195:  */
196: function checkForChanges() {
197:   console.log(`⏳ Checking for filesystem changes after i18n execution...`);
198:   let statusResult = '';
199:   let hasChanges = false;
200:   try {
201:     statusResult = execSync('git status --porcelain', { encoding: 'utf-8' });
202:     hasChanges = statusResult.trim().length > 0;
203:   } catch (error) {
204:     console.error('❌ Error checking for changes:', error);
205:     return true;
206:   }
207: 
208:   if (hasChanges) {
209:     // Print the full diff to the console
210:     console.warn(`❗ Changes found in the translation files. Please review them.`);
211:     execSync('git  --no-pager diff', { stdio: 'inherit' });
212:   }
213:   return hasChanges;
